from pathlib import Path
import hashlib

source_path = Path('tools/ats_question_triage.py')
regression_path = Path('tests/test_ats_question_triage_autonomous.py')
immutable_path = Path('tests/test_ats_question_triage.py')
expected_blob = '8b4d37223ee08c0add0d5b349875a8e8983cd0d9'


def git_blob_sha1(data):
    header = b'blob ' + str(len(data)).encode('ascii') + b'\0'
    return hashlib.sha1(header + data).hexdigest()


immutable_before = immutable_path.read_bytes()
if git_blob_sha1(immutable_before) != expected_blob:
    raise RuntimeError('Immutable test Git blob identity mismatch')

if not source_path.is_file() or not regression_path.is_file():
    raise RuntimeError('Expected completed implementation and regressions are missing')

original_source = source_path.read_text(encoding='utf-8')
original_tests = regression_path.read_text(encoding='utf-8')

required_source = [
    'mismatched_contact_control',
    'field.get("ambiguous", False) is not False',
]
required_tests = [
    'def test_mismatched_contact_controls_require_review(',
    'def test_nonboolean_ambiguity_metadata_requires_review(',
]

if any(item not in original_source for item in required_source):
    raise RuntimeError('Previously completed classifier safeguards are missing')

if any(item not in original_tests for item in required_tests):
    raise RuntimeError('Previously completed autonomous regressions are missing')

if 'invalid_field_metadata' in original_source:
    raise RuntimeError('Requested metadata safeguard may already be implemented')

if 'def test_malformed_contact_metadata_requires_review(' in original_tests:
    raise RuntimeError('Requested autonomous regressions already exist')

anchor = '    question = re.sub('
if original_source.count(anchor) != 1:
    raise RuntimeError('Expected question normalization anchor not found exactly once')

insert = '''    for metadata_key in ('question', 'label'):
        if metadata_key in field and not isinstance(field[metadata_key], str):
            return {'status': 'human_review', 'reason': 'invalid_field_metadata'}
    if 'label' in field and field['label'] and not field['label'].strip():
        return {'status': 'human_review', 'reason': 'invalid_field_metadata'}
'''

additional_tests = '''

@pytest.mark.parametrize('bad_value', [
    None,
    False,
    True,
    0,
    1,
    0.0,
    [],
    {},
    (),
    ['Email'],
    {'value': 'Email'},
])
@pytest.mark.parametrize('metadata_key', ['question', 'label'])
def test_malformed_contact_metadata_requires_review(metadata_key, bad_value):
    field = {
        'question': 'Email',
        'label': 'Email',
        'type': 'email',
        'ambiguous': False,
    }
    field[metadata_key] = bad_value
    result = classify_field(field, {'email'})
    assert result == {
        'status': 'human_review',
        'reason': 'invalid_field_metadata',
    }


@pytest.mark.parametrize('label', [
    ' ',
    '   ',
    '\\t',
    '\\n',
    ' \\t \\n ',
])
def test_whitespace_only_contact_label_requires_review(label):
    result = classify_field(
        {
            'question': 'Email',
            'label': label,
            'type': 'email',
            'ambiguous': False,
        },
        {'email'},
    )
    assert result == {
        'status': 'human_review',
        'reason': 'invalid_field_metadata',
    }


@pytest.mark.parametrize('question,kind,key', [
    ('Full name', 'text', 'full_name'),
    ('Email', 'email', 'email'),
    ('Phone', 'tel', 'phone'),
    ('LinkedIn', 'url', 'linkedin'),
    ('GitHub', 'url', 'github'),
])
def test_missing_label_preserves_verified_candidate(question, kind, key):
    result = classify_field(
        {'question': question, 'type': kind, 'ambiguous': False},
        {key},
    )
    assert result == {'status': 'verified_candidate', 'profile_key': key}


@pytest.mark.parametrize('question,kind,key', [
    ('Full name', 'text', 'full_name'),
    ('Email', 'email', 'email'),
    ('Phone', 'tel', 'phone'),
    ('LinkedIn', 'url', 'linkedin'),
    ('GitHub', 'url', 'github'),
])
def test_empty_string_label_preserves_verified_candidate(question, kind, key):
    result = classify_field(
        {
            'question': question,
            'label': '',
            'type': kind,
            'ambiguous': False,
        },
        {key},
    )
    assert result == {'status': 'verified_candidate', 'profile_key': key}


@pytest.mark.parametrize('question_value', ['', None])
def test_missing_or_empty_question_fallback_is_distinguished(question_value):
    field = {
        'label': 'Email',
        'type': 'email',
        'ambiguous': False,
    }
    if question_value is not None:
        field['question'] = question_value
    result = classify_field(field, {'email'})
    assert result == {'status': 'verified_candidate', 'profile_key': 'email'}


def test_explicit_null_question_does_not_fallback_to_verified_label():
    result = classify_field(
        {
            'question': None,
            'label': 'Email',
            'type': 'email',
            'ambiguous': False,
        },
        {'email'},
    )
    assert result == {
        'status': 'human_review',
        'reason': 'invalid_field_metadata',
    }


def test_valid_contact_label_whitespace_normalization_is_preserved():
    result = classify_field(
        {
            'question': 'Email',
            'label': '  Email  ',
            'type': 'email',
            'ambiguous': False,
        },
        {'email'},
    )
    assert result == {'status': 'verified_candidate', 'profile_key': 'email'}


def test_mixed_metadata_validation_preserves_triage_order():
    fields = [
        {'question': 'Email', 'label': 'Email', 'type': 'email', 'ambiguous': False},
        {'question': None, 'label': 'Email', 'type': 'email', 'ambiguous': False},
        {'question': 'Phone', 'label': '   ', 'type': 'tel', 'ambiguous': False},
        {'question': 'GitHub', 'type': 'url', 'ambiguous': False},
        {'question': 'LinkedIn', 'label': 'LinkedIn', 'type': 'email', 'ambiguous': False},
        {'question': 'Email', 'label': 'Email', 'type': 'email', 'ambiguous': None},
        {'question': 'Referee email', 'label': 'Referee email', 'type': 'email', 'ambiguous': False},
    ]
    results = triage_fields(fields, {'email', 'phone', 'github', 'linkedin'})
    assert results == [
        {'status': 'verified_candidate', 'profile_key': 'email'},
        {'status': 'human_review', 'reason': 'invalid_field_metadata'},
        {'status': 'human_review', 'reason': 'invalid_field_metadata'},
        {'status': 'verified_candidate', 'profile_key': 'github'},
        {'status': 'human_review', 'reason': 'mismatched_contact_control'},
        {'status': 'human_review', 'reason': 'ambiguous_question'},
        {'status': 'human_review', 'reason': 'unknown_question'},
    ]


def test_malformed_metadata_never_exposes_candidate_or_answer():
    result = classify_field(
        {
            'question': 'Full name',
            'label': False,
            'type': 'text',
            'ambiguous': False,
        },
        {'full_name'},
    )
    assert result == {
        'status': 'human_review',
        'reason': 'invalid_field_metadata',
    }
    assert 'profile_key' not in result
    assert 'answer' not in result
    assert 'value' not in result
'''

updated_source = original_source.replace(anchor, insert + anchor, 1)
updated_tests = original_tests.rstrip('\n') + '\n' + additional_tests

compile(updated_source, str(source_path), 'exec')
compile(updated_tests, str(regression_path), 'exec')

if immutable_path.read_bytes() != immutable_before:
    raise RuntimeError('Immutable test changed before implementation')

source_written = False
tests_written = False
try:
    source_path.write_text(updated_source, encoding='utf-8')
    source_written = True
    regression_path.write_text(updated_tests, encoding='utf-8')
    tests_written = True
    if immutable_path.read_bytes() != immutable_before:
        raise RuntimeError('Immutable test changed during implementation')
    if git_blob_sha1(immutable_path.read_bytes()) != expected_blob:
        raise RuntimeError('Immutable test Git blob identity changed')
except BaseException:
    if source_written:
        source_path.write_text(original_source, encoding='utf-8')
    if tests_written:
        regression_path.write_text(original_tests, encoding='utf-8')
    raise
